<span class="line"><span style="color:#85E89D;">        java-version</span><span style="color:#E1E4E8;">: [</span><span style="color:#79B8FF;">17</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">21</span><span style="color:#E1E4E8;">]  </span><span style="color:#6A737D;"># 支持多Java版本</span></span>
